/*
 * GENERATED by scripts/generate-character-rows.mjs — do not edit by hand.
 * Source: docs/research/character-2026-10/characters.json
 *
 * WHY: a product's BRAND is who made it, its FRANCHISE is what it is from, and
 *      its CHARACTER is WHO USED IT. The third is the strongest buying signal
 *      in this corpus and had nowhere to live: 495 character pages sat in the
 *      local crawl with nothing in the catalogue referencing them. Nobody
 *      searches "Attack Ring MA-04"; they search "Tyson's Dragoon".
 *
 * WHAT: 320 declarations plus one factory, modelled on
 *       `franchise-rows.ts` — which is itself modelled on `brand-rows.ts`.
 *
 * EXPORTS:
 *   CHARACTER_ROWS       — Partial<CategoryDocument>[], categoryType:"character"
 *   CHARACTER_ROW_COUNT  — asserted by the seed so a silent drop is loud
 *   CHARACTER_SLUGS      — what a bey's `owner` may point at
 *
 * ── 🛑 WHAT IS NOT HERE, AND WHY ──────────────────────────────────────────
 *
 * **112 people with no bey**, left out deliberately. A character row answers
 * "show me their beys"; a character with none can never answer it, so the row
 * would be a facet with no possible consumer — announcers, commentators,
 * parents, a DJ. They remain in the extraction, which is where a fact about
 * the corpus belongs.
 *
 * **10 bit-beasts**, which the wiki files under `Characters` with the tag
 * `Avatar` — Valtryek, Spryzen, Dragon and seven more. A bit-beast is BOUND to
 * a bey; it does not own one, so it must not become an owner row. They carry
 * the longest "chains" in the whole corpus (Valtryek's is 13), which is exactly
 * what made them dangerous: those lists are a NAME FAMILY across generations,
 * not a personal succession, and the extraction names the field `beyFamily`
 * for that reason.
 *
 * ── 🛑 EVERY ROW IS `isActive: false` ─────────────────────────────────────
 *
 * `brand-rows.ts` trap 3: *"a row with no product is a DEAD FACET, and worse
 * than absent — it renders as a card in the grid that opens an empty page."*
 * No product carries a character yet. The row still exists, its page resolves,
 * and it is editable in the admin category editor; it is out of the grid and
 * out of search until one flag flips.
 *
 * 🛑 `isActive` is load-bearing here, not boilerplate. Flip a row to `true`
 * when a product actually carries its slug — and ONLY then.
 *
 * ── 🛑 THE OWNER LINK IS NOT NAME-MATCHABLE ───────────────────────────────
 *
 * Deriving it by joining lineup beys against the bey database resolves
 * **273 of 598 (46%)**, and the misses are not a join bug — the two corpora
 * name different objects:
 *
 *     character page (anime) :  Turbo Achilles 00 Dimension
 *     bey database  (product):  Turbo Achilles A4 00 Dimension-S
 *
 * The product spelling carries the Storm Chip code and the regional suffix;
 * the anime says neither. Others have no product row at all. So `owner` is
 * resolved per-bey from the bey's own page, which states it — a declaration
 * rather than a 46%-confidence guess.
 *
 * ── Why tier-0 and outside the forest ─────────────────────────────────────
 *
 * Same as brands and franchises: `position` is NOT set, because these live
 * outside the category forest's DFS numbering and a position inside it would
 * corrupt the ranges `onCategoryWrite` shifts on insert.
 *
 * @tag domain:categories
 * @tag layer:seed
 * @tag pattern:shared-literal
 * @tag access:server-only
 * @tag consumers:seed/categories-seed-data.ts
 * @tag sideEffects:none
 */

import type { CategoryDocument } from "../../features/categories/schemas";
/* 🛑 `constants/field-names`, NOT the schema copy — there are two
 * `CATEGORY_FIELDS` and only this one carries `CATEGORY_TYPE_VALUES`.
 * `categories-seed-data.ts` imports this one; matching it is what keeps the
 * discriminator a single spelling. Same reasoning as `franchise-rows.ts`. */
import { CATEGORY_FIELDS } from "../../constants/field-names";
import { seedPhoto } from "./media";

export interface CharacterSeedInput {
  /** Without the `character-` prefix. A bey's `owner` matches on this, never the name. */
  slug: string;
  name: string;
  /** As the Japanese release names them — the reason the join is by slug. */
  jpName?: string;
  romaji?: string;
  /** How many beys the anime succession lists. Zero never reaches this file. */
  lineupLength: number;
  description: string;
  sourceUrl: string;
}

export function characterRow(
  input: CharacterSeedInput,
  order: number,
  stamps: { createdBy: string; createdAt: Date; updatedAt: Date },
): Partial<CategoryDocument> {
  const id = `character-${input.slug}`;
  return {
    id,
    slug: id,
    name: input.name,
    categoryType: CATEGORY_FIELDS.CATEGORY_TYPE_VALUES.CHARACTER,
    description: input.description,
    rootId: id,
    parentIds: [],
    childrenIds: [],
    ancestors: [],
    tier: 0,
    path: id,
    isLeaf: true,
    order,
    /*
     * A placeholder tile a real portrait OVERRIDES — same rule as
     * `franchise-rows.ts`: `withGeneratedCoverImage` treats an
     * `/images/seed-tiles/` path as a default rather than a hand-authored
     * decision.
     *
     * 🛑 `icon` stays unset. The taxonomy grid reads `display.icon` FIRST, so
     * an emoji there would beat a real portrait (brand-rows trap 2).
     */
    display: {
      coverImage: seedPhoto(`character-cover-${input.slug}-20261024`, 800, 800),
      showInMenu: false,
      showInFooter: false,
    },
    isFeatured: false,
    /* See the dead-facet rule in this file's header. Not boilerplate. */
    isActive: false,
    isSearchable: false,
    createdBy: stamps.createdBy,
    createdAt: stamps.createdAt,
    updatedAt: stamps.updatedAt,
    seo: {
      title: `${input.name} | LetItRip`,
      description: `${input.name}'s Beyblades — every top they used, in story order. Buy and sell at LetItRip.`,
      keywords: [
        input.name.toLowerCase(),
        ...(input.jpName ? [input.jpName] : []),
        ...(input.romaji ? [input.romaji.toLowerCase()] : []),
        "beyblade",
        "blader",
      ],
    },
  };
}

