export function buildCharacterRows(stamps: {
  createdBy: string;
  createdAt: Date;
  updatedAt: Date;
}): Partial<CategoryDocument>[] {
  return INPUTS.map((input, i) => characterRow(input, i + 1, stamps));
}

export const CHARACTER_ROW_COUNT = INPUTS.length;

/** The slugs a bey's `owner` may point at. */
export const CHARACTER_SLUGS: readonly string[] = INPUTS.map((i) => `character-${i.slug}`);
